from collections import defaultdict

def get_active_bits(n):
	result = []
	i = 0
	while n:
		if n & 1:
			result.append(i)
		i += 1
		n >>= 1
	return result

def get_val(d):
	result = 0
	for (key, val) in d.items():
		if val:
			result += 2 ** key
	return result
t = int(input())
while t:
	n = input().split()
	k = int(n[1])
	n = int(n[0])
	a = [int(_) for _ in input().split()]
	(i, j, ans) = (0, 0, 0)
	dd = defaultdict(int)
	while j < n:
		while j < n and get_val(dd) < k:
			new_bits = get_active_bits(a[j])
			for each in new_bits:
				dd[each] += 1
			j += 1
		while i <= j and get_val(dd) >= k:
			ans += n - j + 1
			new_bits = get_active_bits(a[i])
			for each in new_bits:
				dd[each] -= 1
			i += 1
	print(ans)
	t -= 1
